-- Oracle 19c+ minimal schema + tags

CREATE TABLE artifact_store
(
    hash_hex   CHAR(64) PRIMARY KEY,
    size_bytes NUMBER(19) NOT NULL,
    content    BLOB NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE operation_chain_config
(
    al_id                               VARCHAR2(255 CHAR) PRIMARY KEY,
    allow_run_publication_without_test NUMBER(1) DEFAULT 0 NOT NULL,
    store_type                          VARCHAR2(64) NOT NULL
        CHECK (REGEXP_LIKE(store_type, '^[A-Z][A-Z0-9_-]{0,63}$')),
    store_props                         CLOB NOT NULL CHECK (store_props IS JSON),
    created_at                          TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at                          TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE operation_chain_object
(
    id           NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    al_id        VARCHAR2(255 CHAR) NOT NULL,
    version      VARCHAR2(100) NOT NULL,
    publication_mode VARCHAR2(10) NOT NULL,
    content_hash CHAR(64) NOT NULL,
    size_bytes   NUMBER(19) NOT NULL,
    mime_type    VARCHAR2(100) DEFAULT 'application/xml' NOT NULL,
    created_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by   VARCHAR2(200),
    published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_op_chain UNIQUE (al_id, version, publication_mode)
);


CREATE TABLE operation_chain_publication_stage
(
    stage_id         VARCHAR2(36) PRIMARY KEY,
    al_id            VARCHAR2(255 CHAR) NOT NULL,
    version          VARCHAR2(100) NOT NULL,
    publication_mode VARCHAR2(10) NOT NULL,
    content_hash     CHAR(64) NOT NULL,
    size_bytes       NUMBER(19) NOT NULL,
    mime_type        VARCHAR2(100) NOT NULL,
    created_at       TIMESTAMP NOT NULL,
    created_by       VARCHAR2(200),
    published_at     TIMESTAMP NOT NULL,
    store_fingerprint CHAR(64) NOT NULL,
    staged_at        TIMESTAMP NOT NULL,
    stage_revision   NUMBER(19) DEFAULT 1 NOT NULL,
    CONSTRAINT uq_op_chain_stage UNIQUE (al_id, version, publication_mode)
);

CREATE TABLE operation_chain_publication_stage_tag
(
    stage_id VARCHAR2(36) NOT NULL,
    tag      VARCHAR2(100) NOT NULL,
    CONSTRAINT pk_op_chain_stage_tag PRIMARY KEY (stage_id, tag),
    CONSTRAINT fk_op_chain_stage_tag FOREIGN KEY (stage_id)
        REFERENCES operation_chain_publication_stage (stage_id) ON DELETE CASCADE
);

CREATE INDEX idx_op_chain_stage_age
    ON operation_chain_publication_stage (staged_at, stage_id);

CREATE TABLE operation_chain_tag
(
    al_id VARCHAR2(255 CHAR) NOT NULL,
    tag   VARCHAR2(100) NOT NULL,
    CONSTRAINT pk_operation_chain_tag PRIMARY KEY (al_id, tag),
    CONSTRAINT fk_operation_chain_tag_config FOREIGN KEY (al_id)
        REFERENCES operation_chain_config (al_id) ON DELETE CASCADE
);

CREATE INDEX idx_op_chain_latest_run
    ON operation_chain_object (al_id, publication_mode, published_at DESC, id DESC);
CREATE INDEX idx_op_chain_all
    ON operation_chain_object (al_id, published_at DESC, id DESC);
CREATE INDEX idx_op_chain_by_hash ON operation_chain_object (content_hash);
CREATE INDEX idx_tag_value ON operation_chain_tag (tag);
